  "specVersion": "1.0.0",
  "name": "example-webgl-holographic-foil",
  "title": "Holographic Foil",
  "title_i18n": {
    "zh-CN": "全息箔片",
    "zh-TW": "全息箔片",
    "ja": "ホログラフィック・フォイル",
    "ko": "홀로그래픽 포일",
