    "example",
    "first-party",
    "hero",
    "webgl",
    "webgl2",
    "shader",
    "iridescent",
    "foil",
    "generative",
    "powered-preview",
    "untitled"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
