      "entry": "./example.html"
    },
    "useCase": {
      "query": {
        "en": "Build a self-contained WebGL2 hero of thin-film interference over a crushed foil, palette shifting with viewing angle, cursor-tilted.",
        "zh-CN": "构建自包含 WebGL2 主视觉：褶皱箔片薄膜干涉，调色随视角变化，光标可倾斜。"
      }
    },
    "context": {
